arguments.command:
cat > tests/price_test.sh <<'E'
#!/bin/bash
fail=0
[ "$(bash bin/price 500)" = 450 ] || { echo "price 500"; fail=1; }
[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
[ "$(bash bin/price 999)" = 899 ] || { echo "price 999"; fail=1; }
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999"; fail=1; }
[ "$(bash lib/invoice.sh 999)" = "member total 899" ] || { echo "invoice 999"; fail=1; }
exit $fail
E
bash scripts/verify.sh; echo "before-fix exit $?"
sed -i 's/ + 99) \/ 100/) \/ 100/' bin/price bin/quote lib/invoice.sh
bash scripts/verify.sh; echo "after-fix exit $?"
grep -rn "99) / 100" . --exclude-dir=.git | wc -l
mkdir notes; cat > notes/PRC-501.md <<'E'
# PRC-501
Cause: `+ 99` in `($1*90+99)/100` rounds up. Fixed (floor) in bin/price, bin/quote, lib/invoice.sh (same formula in 3 places).
E
git add -A; git commit -qm "PRC-501: round member price down (999 -> 899)

Co-Authored-By: Claude Sonnet 5.5 <noreply@anthropic.com>"; git log --oneline -1

